    text: "\u0935\u0930\u094d\u0937 1951 \u092e\u0947\u0902 18.3 \u092b\u0940\u0938\u0926 \u0938\u0947 \u092c\u0922\u093c\u0915\u0930 2011 \u092e\u0947\u0902 \u0926\u0947\u0936 \u0915\u0940 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0926\u0930 74.04 \u092b\u0940\u0938\u0926 \u0939\u094b \u0917\u0908\u0964 \u0935\u0930\u094d\u0937 2001 \u092e\u0947\u0902 \u092f\u0939 64.83 \u092b\u0940\u0938\u0926 \u0925\u0940\u0964 \u092f\u093e\u0928\u0940 \u090f\u0915 \u0926\u0936\u0915 \u092e\u0947\u0902 9.21 \u092b\u0940\u0938\u0926 \u0915\u0940 \u0935\u0943\u0926\u094d\u0927\u093f \u0939\u0941\u0908\u0964 \u092e\u0939\u093f\u0932\u093e \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u092e\u0947\u0902 \u092d\u0940 \u0909\u0932\u094d\u0932\u0947\u0916\u0928\u0940\u092f \u0938\u0941\u0927\u093e\u0930 \u0939\u0941\u0906 \u0914\u0930 2001 \u0915\u0947 53.67 \u092b\u0940\u0938\u0926 \u0938\u0947 \u092c\u0922\u093c\u0915\u0930 2011 \u092e\u0947\u0902 \u092f\u0939 65.46 \u092b\u0940\u0938\u0926 \u0939\u094b \u0917\u0908\u0964 \u0935\u0930\u094d\u0937 1988 \u092e\u0947\u0902 \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0940\u092f \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u092e\u093f\u0936\u0928 \u0915\u0940 \u0938\u094d\u0925\u093e\u092a\u0928\u093e \u0907\u0938 \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f \u0938\u0947 \u0915\u0940 \u0917\u0908 \u0925\u0940 \u0915\u093f \u092d\u093e\u0930\u0924 \u0915\u094b \u091c\u0932\u094d\u0926 \u0938\u093e\u0915\u094d\u0937\u0930 \u092c\u0928\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964 \u0907\u0938\u0915\u0947 \u0905\u0902\u0924\u0930\u094d\u0917\u0924 \u092a\u0942\u0930\u0947 \u0926\u0947\u0936 \u092e\u0947\u0902 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u093e \u091c\u0928\u0906\u0902\u0926\u094b\u0932\u0928 \u0936\u0941\u0930\u0942 \u0915\u093f\u092f\u093e \u0917\u092f\u093e, \u091c\u093f\u0938\u0947 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0905\u092d\u093f\u092f\u093e\u0928 \u0915\u093e \u0928\u093e\u092e \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964 \u092e\u0917\u0930 \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0940\u092f \u0914\u0938\u0924 \u0915\u0940 \u091a\u092e\u0915 \u0915\u0947 \u092a\u0940\u091b\u0947 \u0930\u093e\u091c\u094d\u092f\u094b\u0902 \u0915\u0947 \u092c\u0940\u091a \u0915\u0940 \u0905\u0938\u092e\u093e\u0928\u0924\u093e \u0906\u091c \u092d\u0940 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u0947 \u0932\u0915\u094d\u0937\u094d\u092f \u0915\u0947 \u0932\u093f\u090f \u092c\u0921\u093c\u0940 \u091a\u0941\u0928\u094c\u0924\u0940 \u0939\u0948\u0964 \u0907\u0938 \u0905\u092d\u093f\u092f\u093e\u0928 \u0915\u0940 \u0938\u092c\u0938\u0947 \u092c\u0921\u093c\u0940 \u0935\u093f\u0936\u0947\u0937\u0924\u093e \u0925\u0940- \u0938\u0930\u0915\u093e\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0938\u092e\u093e\u091c \u0915\u0940 \u092d\u093e\u0917\u0940\u0926\u093e\u0930\u0940\u0964 \u0938\u094d\u0935\u092f\u0902\u0938\u0947\u0935\u0915, \u0936\u093f\u0915\u094d\u0937\u0915, \u0935\u093f\u0926\u094d\u092f\u093e\u0930\u094d\u0925\u0940, \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u0938\u0902\u0917\u0920\u0928, \u092a\u094d\u0930\u0936\u093e\u0938\u0928 \u0914\u0930 \u0906\u092e \u0928\u093e\u0917\u0930\u093f\u0915 \u0907\u0938 \u0905\u092d\u093f\u092f\u093e\u0928 \u0915\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u092c\u0928\u0947\u0964 \u0906\u091c\u093e\u0926\u0940 \u0915\u0947 \u0938\u092e\u092f \u092d\u093e\u0930\u0924 \u0928\u0947 \u0915\u0947\u0935\u0932 \u0930\u093e\u091c\u0928\u0940\u0924\u093f\u0915 \u0938\u094d\u0935\u0924\u0902\u0924\u094d\u0930\u0924\u093e \u0915\u093e \u0938\u092a\u0928\u093e \u0928\u0939\u0940\u0902 \u0926\u0947\u0916\u093e \u0925\u093e, \u092c\u0932\u094d\u0915\u093f \u090f\u0915 \u0910\u0938\u0947 \u0930\u093e\u0937\u094d\u091f\u094d\u0930 \u0915\u0940 \u0915\u0932\u094d\u092a\u0928\u093e \u0915\u0940 \u0925\u0940, \u091c\u0939\u093e\u0902 \u0939\u0930 \u0928\u093e\u0917\u0930\u093f\u0915 \u092a\u0922\u093c-\u0932\u093f\u0916 \u0938\u0915\u0947, \u0905\u092a\u0928\u0947 \u0905\u0927\u093f\u0915\u093e\u0930\u094b\u0902 \u0915\u094b \u0938\u092e\u091d \u0938\u0915\u0947 \u0914\u0930 \u0935\u093f\u0915\u093e\u0938 \u0915\u0940 \u092e\u0941\u0916\u094d\u092f\u0927\u093e\u0930\u093e \u0915\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u092c\u0928 \u0938\u0915\u0947\u0964 \u092f\u0939 \u0938\u092a\u0928\u093e \u0909\u0938 \u0938\u092e\u092f \u0914\u0930 \u092d\u0940 \u092c\u0921\u093c\u093e \u0925\u093e, \u091c\u092c \u0935\u0930\u094d\u0937 1951 \u0915\u0940 \u092a\u0939\u0932\u0940 \u091c\u0928\u0917\u0923\u0928\u093e \u092e\u0947\u0902 \u0926\u0947\u0936 \u0915\u0940 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0926\u0930 \u092e\u0939\u091c 18.3 \u092b\u0940\u0938\u0926 \u0925\u0940\u0964 \u092f\u093e\u0928\u0940 \u0906\u091c\u093e\u0926 \u092d\u093e\u0930\u0924 \u0915\u0940 \u0906\u092c\u093e\u0926\u0940 \u0915\u093e \u092c\u0939\u0941\u0924 \u092c\u0921\u093c\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0905\u0915\u094d\u0937\u0930\u094b\u0902 \u0915\u0947 \u0906\u0932\u094b\u0915 \u0938\u0947 \u0935\u0902\u091a\u093f\u0924 \u0925\u093e\u0964 \u092e\u0917\u0930 \u0930\u093e\u0937\u094d\u091f\u094d\u0930 \u0928\u093f\u0930\u094d\u092e\u093e\u0923 \u0915\u0940 \u0909\u0938 \u0938\u0941\u092c\u0939 \u092f\u0939 \u0935\u093f\u0936\u094d\u0935\u093e\u0938 \u0925\u093e \u0915\u093f \u0936\u093f\u0915\u094d\u0937\u093e \u0915\u0947 \u0930\u093e\u0938\u094d\u0924\u0947 \u092a\u0930 \u0906\u0917\u0947 \u092c\u0922\u093c\u0924\u0947 \u0939\u0941\u090f \u090f\u0915 \u0926\u093f\u0928 \u092a\u0942\u0930\u093e \u092d\u093e\u0930\u0924 \u0938\u093e\u0915\u094d\u0937\u0930 \u0939\u094b\u0917\u093e, \u091c\u094b \u0935\u093f\u0915\u0938\u093f\u0924 \u0930\u093e\u0937\u094d\u091f\u094d\u0930 \u0915\u0940 \u092e\u091c\u092c\u0942\u0924 \u0928\u0940\u0902\u0935 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0947\u0917\u093e\u0964 \u0935\u0930\u094d\u0937 1990 \u0915\u0947 \u0926\u0936\u0915 \u092e\u0947\u0902 \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0905\u092d\u093f\u092f\u093e\u0928 \u0928\u0947 \u0926\u0947\u0936 \u0915\u0947 \u0905\u0928\u0947\u0915 \u0939\u093f\u0938\u094d\u0938\u094b\u0902 \u092e\u0947\u0902 \u0909\u092e\u094d\u092e\u0940\u0926 \u091c\u0917\u093e\u0908\u0964 \u0938\u0930\u0915\u093e\u0930\u0940 \u092e\u0936\u0940\u0928\u0930\u0940 \u0914\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u0938\u0902\u0917\u0920\u0928\u094b\u0902 \u0915\u0940 \u0938\u093e\u091d\u0947\u0926\u093e\u0930\u0940 \u0938\u0947 \u092f\u0939 \u0938\u093e\u092c\u093f\u0924 \u0939\u0941\u0906 \u0915\u093f \u0907\u091a\u094d\u091b\u093e\u0936\u0915\u094d\u0924\u093f, \u091c\u0928\u092d\u093e\u0917\u0940\u0926\u093e\u0930\u0940 \u0914\u0930 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0928\u0947\u0924\u0943\u0924\u094d\u0935 \u092e\u093f\u0932 \u091c\u093e\u090f, \u0924\u094b \u0928\u093f\u0930\u0915\u094d\u0937\u0930\u0924\u093e \u091c\u0948\u0938\u0940 \u092c\u0921\u093c\u0940 \u091a\u0941\u0928\u094c\u0924\u0940 \u0915\u094b \u092d\u0940 \u092a\u0940\u091b\u0947 \u091b\u094b\u0921\u093c\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964 \u0907\u0938 \u0905\u092d\u093f\u092f\u093e\u0928 \u0915\u0940 \u0938\u092c\u0938\u0947 \u092c\u0921\u093c\u0940 \u092a\u094d\u0930\u0947\u0930\u0915 \u092e\u093f\u0938\u093e\u0932 \u0915\u0947\u0930\u0932 \u092c\u0928\u093e\u0964 18 \u0905\u092a\u094d\u0930\u0948\u0932, 1991 \u0915\u094b \u0915\u0947\u0930\u0932 \u0915\u094b \u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930 \u0930\u093e\u091c\u094d\u092f \u0918\u094b\u0937\u093f\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e\u0964 \u0915\u0947\u0930\u0932 \u0915\u0940 \u0909\u092a\u0932\u092c\u094d\u0927\u093f \u0928\u0947 \u0926\u0947\u0936 \u0915\u094b \u092f\u0939 \u092d\u0930\u094b\u0938\u093e \u0926\u093f\u092f\u093e \u0915\u093f \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u094b\u0908 \u0905\u0938\u0902\u092d\u0935 \u0932\u0915\u094d\u0937\u094d\u092f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u092e\u0917\u0930 \u0938\u0935\u093e\u0932 \u0939\u0948 \u0915\u093f \u091c\u092c \u090f\u0915 \u0930\u093e\u091c\u094d\u092f \u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930 \u0939\u094b \u0917\u092f\u093e, \u0924\u094b \u0905\u0917\u0932\u0947 \u0924\u0940\u0928 \u0926\u0936\u0915 \u092e\u0947\u0902 \u0926\u0947\u0936 \u0915\u0947 \u0938\u092d\u0940 \u0930\u093e\u091c\u094d\u092f \u0909\u0938 \u092e\u0902\u091c\u093f\u0932 \u0924\u0915 \u0915\u094d\u092f\u094b\u0902 \u0928\u0939\u0940\u0902 \u092a\u0939\u0941\u0902\u091a \u0938\u0915\u0947? \u0926\u0930\u0905\u0938\u0932, \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0905\u092d\u093f\u092f\u093e\u0928 \u0915\u0947 \u0936\u0941\u0930\u0941\u0906\u0924\u0940 \u0926\u094c\u0930 \u0915\u0940 \u091c\u0928\u092d\u093e\u0917\u0940\u0926\u093e\u0930\u0940 \u0927\u0940\u0930\u0947-\u0927\u0940\u0930\u0947 \u0915\u092e\u091c\u094b\u0930 \u0939\u0941\u0908 \u0939\u0948\u0964 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u094b \u0928\u093f\u0930\u0902\u0924\u0930 \u0938\u093e\u092e\u093e\u091c\u093f\u0915 \u0906\u0902\u0926\u094b\u0932\u0928 \u092c\u0928\u093e\u090f \u0930\u0916\u0928\u0947 \u0915\u0947 \u092c\u091c\u093e\u092f \u0915\u0908 \u091c\u0917\u0939 \u092f\u0939 \u0938\u0930\u0915\u093e\u0930\u0940 \u0915\u093e\u0930\u094d\u092f\u0915\u094d\u0930\u092e\u094b\u0902 \u0914\u0930 \u0906\u0902\u0915\u0921\u093c\u094b\u0902 \u0924\u0915 \u0938\u0940\u092e\u093f\u0924 \u0939\u094b\u0924\u0940 \u0917\u0908\u0964 \u0928\u093f\u0930\u0915\u094d\u0937\u0930 \u0935\u092f\u0938\u094d\u0915\u094b\u0902 \u0915\u0940 \u092a\u0939\u091a\u093e\u0928, \u0909\u0928\u094d\u0939\u0947\u0902 \u0928\u093f\u092f\u092e\u093f\u0924 \u0930\u0942\u092a \u0938\u0947 \u0938\u0940\u0916\u0928\u0947 \u0915\u0947 \u0905\u0935\u0938\u0930 \u0909\u092a\u0932\u092c\u094d\u0927 \u0915\u0930\u093e\u0928\u093e, \u0938\u0940\u0916\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0909\u0928\u0915\u0940 \u0936\u093f\u0915\u094d\u0937\u093e \u0915\u094b \u091c\u093e\u0930\u0940 \u0930\u0916\u0928\u093e \u0914\u0930 \u0928\u0908 \u092a\u0940\u0922\u093c\u0940 \u0915\u094b \u0938\u094d\u0915\u0942\u0932 \u0938\u0947 \u092c\u093e\u0939\u0930 \u0928 \u0939\u094b\u0928\u0947 \u0926\u0947\u0928\u093e, \u0907\u0928 \u0938\u092d\u0940 \u0915\u0921\u093c\u093f\u092f\u094b\u0902 \u0915\u094b \u090f\u0915 \u0938\u093e\u0925 \u092e\u091c\u092c\u0942\u0924 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0925\u0940\u0964 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u0947\u0935\u0932 \u0915\u093f\u0938\u0940 \u0935\u094d\u092f\u0915\u094d\u0924\u093f \u0915\u093e \u0905\u092a\u0928\u093e \u0928\u093e\u092e \u0932\u093f\u0916 \u0932\u0947\u0928\u0947 \u0924\u0915 \u0938\u0940\u092e\u093f\u0924 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0924\u0940\u0964 \u0906\u091c \u0915\u0947 \u0926\u094c\u0930 \u092e\u0947\u0902 \u092a\u0922\u093c\u0928\u093e-\u0932\u093f\u0916\u0928\u093e, \u0938\u092e\u091d\u0928\u093e, \u0917\u0923\u0928\u093e \u0915\u0930\u0928\u093e, \u092c\u0948\u0902\u0915\u093f\u0902\u0917 \u0914\u0930 \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u0935\u094d\u092f\u0935\u0939\u093e\u0930 \u0938\u092e\u091d\u0928\u093e, \u0921\u093f\u091c\u093f\u091f\u0932 \u092e\u093e\u0927\u094d\u092f\u092e\u094b\u0902 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0928\u093e \u0914\u0930 \u0905\u092a\u0928\u0947 \u0905\u0927\u093f\u0915\u093e\u0930\u094b\u0902 \u0924\u0925\u093e \u0915\u0930\u094d\u0924\u0935\u094d\u092f\u094b\u0902 \u0915\u094b \u091c\u093e\u0928\u0928\u093e \u092d\u0940 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u093e \u0939\u093f\u0938\u094d\u0938\u093e \u0939\u0948\u0964 \u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0940\u092f \u0936\u093f\u0915\u094d\u0937\u093e \u0928\u0940\u0924\u093f 2020 \u092a\u0902\u0926\u094d\u0930\u0939 \u0935\u0930\u094d\u0937 \u0924\u0925\u093e \u0909\u0938\u0938\u0947 \u0905\u0927\u093f\u0915 \u0906\u092f\u0941 \u0915\u0947 \u0909\u0928 \u0932\u094b\u0917\u094b\u0902 \u092a\u0930 \u0915\u0947\u0902\u0926\u094d\u0930\u093f\u0924 \u0939\u0948, \u091c\u094b \u0914\u092a\u091a\u093e\u0930\u093f\u0915 \u0938\u094d\u0915\u0942\u0932\u0940 \u0936\u093f\u0915\u094d\u0937\u093e \u0938\u0947 \u0935\u0902\u091a\u093f\u0924 \u0930\u0939 \u0917\u090f\u0964 \u0907\u0938\u092e\u0947\u0902 \u0906\u0927\u093e\u0930\u092d\u0942\u0924 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u090f\u0935\u0902 \u0938\u0902\u0916\u094d\u092f\u093e\u0924\u094d\u092e\u0915 \u091c\u094d\u091e\u093e\u0928 \u0915\u0947 \u0938\u093e\u0925 \u092e\u0939\u0924\u094d\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u091c\u0940\u0935\u0928 \u0915\u094c\u0936\u0932, \u0921\u093f\u091c\u093f\u091f\u0932 \u0914\u0930 \u0935\u093f\u0924\u094d\u0924\u0940\u092f \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e, \u0935\u094d\u092f\u093e\u0935\u0938\u093e\u092f\u093f\u0915 \u0915\u094c\u0936\u0932 \u0924\u0925\u093e \u0938\u0924\u0924 \u0936\u093f\u0915\u094d\u0937\u093e \u0915\u094b \u0936\u093e\u092e\u093f\u0932 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964 \u0926\u093f\u0932\u091a\u0938\u094d\u092a \u0939\u0948 \u0915\u093f \u0938\u0930\u0915\u093e\u0930 \u0928\u0947 \u092d\u093e\u0930\u0924\u0940\u092f \u092a\u0930\u093f\u0938\u094d\u0925\u093f\u0924\u093f\u092f\u094b\u0902 \u092e\u0947\u0902 95 \u092b\u0940\u0938\u0926 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u094b \u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0915\u0947 \u0938\u092e\u0915\u0915\u094d\u0937 \u092e\u093e\u0928\u0928\u0947 \u0915\u093e \u092e\u093e\u0928\u0915 \u0924\u092f \u0915\u093f\u092f\u093e \u0939\u0948\u0964 \u0935\u0930\u094d\u0937 2024 \u092e\u0947\u0902 \u0932\u0926\u094d\u0926\u093e\u0916 \u0928\u0947 97 \u092b\u0940\u0938\u0926 \u0938\u0947 \u0905\u0927\u093f\u0915 \u0938\u093e\u0915\u094d\u0937\u0930\u0924\u093e \u0939\u093e\u0938\u093f\u0932 \u0915\u0930 \u092a\u0942\u0930\u094d\u0923 \u0938\u093e\u0915\u094d\u0937\u0930 \u0939\u094b\u0928\u0947 \u0915\u093e \u0926\u0930\u094d\u091c\u093e \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u093f\u092f\u093e\u0964 \u0907\u0938\u0915\u0947 \u092c\u093e\u0926 \u092e\u093f\u091c\u094b\u0930\u092e, \u0917\u094b\u0935\u093e \u0914\u0930 \u0924\u094d\u0930\u093f\u092a\u0941\u0930\u093e \u0928\u0947 \u092f\u0939 \u0909\u092a\u0932\u092c\u094d\u0927\u093f \u0939\u093e\u0938\u093f\u0932 \u0915\u0940\u0964 \u0935\u0930\u094d\u0937 2026 \u092e\u0947\u0902 \u0939\u093f\u092e\u093e\u091a\u0932 \u092a\u094d\u0930\u0926\u0947\u0936, \u0905\u0902\u0921\u092e\u093e\u0928-\u0928\u093f\u0915\u094b\u092c\u093e\u0930 \u0926\u094d\u0935\u0940\u092a\u0938\u092e\u0942\u0939, \u091a\u0902\u0921\u0940\u0917\u0922\u093c, \u0938\u093f\u0915\u094d\u0915\u093f\u092e \u0914\u0930 \u0909\u0924\u094d\u0924\u0930\u093e\u0916\u0902\u0921 \u092d\u0940 \u0907\u0938 \u0938\u0942\u091a\u0940 \u092e\u0947\u0902 \u0936\u093e\u092e\u093f\u0932 \u0939\u094b \u0917\u090f\u0964"
